import React from 'react'
import styles from './AlertSettingsScreen.module.css'

export default function AlertSettingsScreen() {
	return (
		<div className={styles.container}>
			<h3 className={styles.title}>アラート設定</h3>
			<p>アラート設定画面（簡易版）</p>
		</div>
	)
}
